import { readdirSync, readFileSync, statSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

// Since generator 2.3.0 (2026-10-14, docs/sessions/2026-10-14-preflight-generator-spec.md)
// the Reasonable Cause Statement's cause narrative is written by our staff from the
// customer's answers (FilingYearData.rcsAdminNarrative; pre-flight A32 blocks the
// package until it exists). Public copy must not call it "auto-generated".
function walk(dir: string): string[] {
  return readdirSync(join(process.cwd(), dir)).flatMap((name) => {
    const rel = join(dir, name);
    if (statSync(join(process.cwd(), rel)).isDirectory()) return walk(rel);
    return /\.(tsx?|md)$/.test(name) && !/\.test\.tsx?$/.test(name) ? [rel] : [];
  });
}
const FILES = [...walk("src/lib"), ...walk("src/app"), ...walk("content/blog")];
const AUTO_RCS = /auto-?generat[\s\S]{0,200}reasonable[- ]cause|reasonable[- ]cause[\s\S]{0,200}auto-?generat/i;

describe("Reasonable Cause Statement wording", () => {
  it("guard regex catches the retired claim and allows the current wording", () => {
    expect(AUTO_RCS.test("The reasonable cause statement is auto-generated by our wizard.")).toBe(true);
    expect(AUTO_RCS.test("Our auto-generated, accountant-reviewed Reasonable Cause Statement")).toBe(true);
    expect(AUTO_RCS.test("We write the Reasonable Cause Statement from the facts you give us.")).toBe(false);
  });

  it.each(FILES)("%s never calls the reasonable cause statement auto-generated", (file) => {
    const match = readFileSync(join(process.cwd(), file), "utf8").match(AUTO_RCS);
    expect(match?.[0], file).toBeUndefined();
  });
});
